import 'dart:math';
enum HazardType { explosiveBarrel, toxicLeak, warpRift, sentryTurret, powerNode }
class ArenaHazard { final String id; final HazardType type; double x,y,radius,health,timer; bool active; ArenaHazard({required this.id,required this.type,required this.x,required this.y,required this.radius,this.health=1,this.timer=0,this.active=true}); void update(double dt){if(!active)return;timer+=dt;if(type==HazardType.toxicLeak && timer>1.5)timer=0;} bool contains(double px,double py)=>active&&pow(px-x,2)+pow(py-y,2)<=radius*radius; Map<String,dynamic> toJson()=>{'id':id,'type':type.name,'x':x,'y':y,'radius':radius,'health':health,'timer':timer,'active':active}; }
class ArenaHazardSystem { final List<ArenaHazard> hazards=[]; int _nextId=0; ArenaHazard add(HazardType type,{required double x,required double y,double radius=52,double health=1}){final h=ArenaHazard(id:'hazard_${_nextId++}',type:type,x:x,y:y,radius:radius,health:health);hazards.add(h);return h;} List<ArenaHazard> hazardsAt(double x,double y)=>hazards.where((h)=>h.contains(x,y)).toList(growable:false); void damage(String id,double amount){final h=hazards.where((e)=>e.id==id).firstOrNull;if(h==null||!h.active)return;h.health-=max(0.0,amount);if(h.health<=0){h.active=false;if(h.type==HazardType.explosiveBarrel||h.type==HazardType.powerNode)h.timer=0;}} void update(double dt){for(final h in hazards)h.update(dt);hazards.removeWhere((h)=>!h.active&&h.timer>5);} void loadJson(dynamic raw){if(raw is! List)return;hazards.clear();for(final entry in raw){if(entry is! Map||entry['id'] is! String||entry['type'] is! String)continue;final type=HazardType.values.where((e)=>e.name==entry['type']).firstOrNull;if(type==null)continue;final h=ArenaHazard(id:entry['id'] as String,type:type,x:entry['x'] is num?(entry['x'] as num).toDouble():0,y:entry['y'] is num?(entry['y'] as num).toDouble():0,radius:entry['radius'] is num?(entry['radius'] as num).toDouble():52,health:entry['health'] is num?(entry['health'] as num).toDouble():1,timer:entry['timer'] is num?(entry['timer'] as num).toDouble():0,active:entry['active']!=false);hazards.add(h);final suffix=int.tryParse(h.id.split('_').last)??0;if(suffix>=_nextId)_nextId=suffix+1;}} }
extension _HazardFirstOrNull<T> on Iterable<T>{T? get firstOrNull=>isEmpty?null:first;}
